// Normalizador & Validador de Identidade Estrita (Vinícius Caetano)
const body = $json.body || $json;
const update = body;
const msg = update.message || {};
const callback = update.callback_query || {};

const userId = String(msg.from?.id || callback.from?.id || body.sender || 'UNKNOWN');
const isMaster = (userId === '2140439370' || userId.includes('5511') || userId.includes('6683'));

const rawText = (msg.text || callback.data || body.text || '').trim();
const threadId = msg.message_thread_id || callback.message?.message_thread_id || 0;
const chatId = msg.chat?.id || callback.message?.chat?.id || body.chatId || '-1004493467706';

return [{
  json: {
    isMaster,
    userId,
    chatId,
    threadId,
    rawText,
    source: 'TELEGRAM',
    timestamp: new Date().toISOString()
  }
}];

// Classificador Semântico Multicamada — Regras de Ouro e Soberania
const item = $json;
const text = item.rawText;
const threadId = item.threadId;

let domain = 'UNKNOWN';
let priority = 'NORMAL';

if (text.includes('youtube.com') || text.includes('youtu.be')) {
  domain = 'SECOND_BRAIN_STUDY';
  priority = 'HIGH';
} else if (threadId === 6 || text.startsWith('/estudo') || text.startsWith('/dossie')) {
  domain = 'SECOND_BRAIN_STUDY';
} else if (threadId === 5 || text.startsWith('/voz') || text.startsWith('/audio') || text.startsWith('arch_voice')) {
  domain = 'MEDIA_NEURAL_VOICE';
} else if (text.startsWith('arch_reels') || text.startsWith('/reels') || text.startsWith('/trailer')) {
  domain = 'MEDIA_CINEMA_VIDEO';
} else if (threadId === 4 || text.startsWith('arch_') || text.startsWith('/deploy') || text.startsWith('/software')) {
  domain = 'SOFTWARE_ENTERPRISE_DEPLOY';
} else if (threadId === 7 || text.startsWith('/status') || text.startsWith('/telemetria') || text.startsWith('devops_')) {
  domain = 'DEVOPS_SENTINEL';
} else if (text.startsWith('/diario') || text.length > 120) {
  domain = 'SECOND_BRAIN_JOURNAL';
} else {
  domain = 'EXECUTIVE_COMMAND_MENU';
}

return [{
  json: {
    ...item,
    domain,
    priority,
    routedAt: new Date().toISOString()
  }
}];

// Extração & Higienização de Link YouTube (Regra 18)
const text = $json.rawText;
const match = text.match(/(?:v=|\/|youtu\.be\/|embed\/|shorts\/)([A-Za-z0-9_-]{11})/);
const videoId = match ? match[1] : '';
const cleanUrl = videoId ? `https://www.youtube.com/watch?v=${videoId}` : text;

return [{
  json: {
    ...$json,
    videoId,
    cleanUrl,
    dissectionStage: 'INGESTION_VERIFIED'
  }
}];

// Formatação de Entrada de Diário & TCC (Regra 17)
const text = $json.rawText.replace('/diario', '').trim();
const now = new Date();
const dateStr = now.toISOString().split('T')[0];
const timeStr = now.toTimeString().split(' ')[0].substring(0, 5);

const entry = `\n\n### ⏱️ ${dateStr} ${timeStr} — Reflexão Registrada\n${text}\n\n---\n`;

return [{
  json: {
    ...$json,
    journalEntry: entry,
    date: dateStr,
    time: timeStr,
    targetBook: 'DIARIO_DE_BORDO_ITZREAL.md'
  }
}];

// Enriquecimento de Locução Paulistana & Microfades (Regra 13)
let text = $json.rawText.replace(/^\/voz|arch_voice/i, '').trim();
if (!text) text = 'Fala aí Vinícius, ecossistema ativo com voz calibrada e decupagem Hann sem corte mecânico.';

return [{
  json: {
    ...$json,
    cleanSpeechText: text,
    voiceModel: 'minha-voz',
    voiceId: 'd34eb157e1e7474c98c9c63d79f7ce9a',
    temperature: 0.85,
    top_p: 0.88,
    preserveBreathsMs: 160
  }
}];

// Auditoria de Arquétipo & Scaffolding de Software (Regras 1 a 12)
let arch = 'roulette';
const text = $json.rawText;
if (text.includes('luxury')) arch = 'luxury';
else if (text.includes('saas')) arch = 'saas';
else if (text.includes('3d')) arch = '3d';
else if (text.includes('ecom')) arch = 'ecom';
else if (text.includes('portfolio')) arch = 'portfolio';

return [{
  json: {
    ...$json,
    archetype: arch,
    cssIsolation: '.uiv_scoped_strict',
    zeroGenericTags: true,
    targetRepoProfile: 'vn-24k',
    deployTarget: 'VERCEL_PRODUCTION'
  }
}];

// Coleta de Telemetria de Infraestrutura & Auto-Cura
return [{
  json: {
    ...$json,
    monitoredServices: [
      'WhatsApp Bridge (Porta 5005)',
      'Cloudflared Tunnels',
      'Telegram Dispatcher',
      'Render PostgreSQL 16'
    ],
    healthStatus: 'ALL_ENGINES_OPERATIONAL'
  }
}];
